import { SettingsError, type Settings, type SettingsStore } from './store.js';

export async function saveSettings(store: SettingsStore, settings: Settings): Promise<boolean> {
  try {
    store.write(settings);
  } catch (err) {
    throw new SettingsError('failed to save settings', { cause: err });
  }
  return true;
}
